57	    pub(crate) fn sort_linked(&mut self, list: usize) -> usize {
58	        let mut list = list;
59	        let mut in_size: i32 = 1;
60	
61	        loop {
62	            let mut p = list;
63	            list = NIL;
64	            let mut tail = NIL;
65	            let mut num_merges = 0;
66	
67	            while p != NIL {
68	                num_merges += 1;
69	                let mut q = p;
70	                let mut p_size: i32 = 0;
71	                for _ in 0..in_size {
72	                    p_size += 1;
73	                    q = self.nodes[q].next_z;
74	                    if q == NIL {
75	                        break;
76	                    }
77	                }
78	                let mut q_size = in_size;
79	
80	                while p_size > 0 || (q_size > 0 && q != NIL) {
81	                    let e;
82	                    if p_size == 0 {
83	                        e = q;
84	                        q = self.nodes[q].next_z;
85	                        q_size -= 1;
86	                    } else if q_size == 0 || q == NIL {
87	                        e = p;
88	                        p = self.nodes[p].next_z;
89	                        p_size -= 1;
90	                    } else if self.nodes[p].z <= self.nodes[q].z {
91	                        e = p;
92	                        p = self.nodes[p].next_z;
93	                        p_size -= 1;
94	                    } else {
95	                        e = q;
96	                        q = self.nodes[q].next_z;
97	                        q_size -= 1;
98	                    }
99	
100	                    if tail != NIL {
101	                        self.nodes[tail].next_z = e;
102	                    } else {
103	                        list = e;
104	                    }
105	
106	                    self.nodes[e].prev_z = tail;
107	                    tail = e;
108	                }
109	
110	                p = q;
111	            }
112	
113	            self.nodes[tail].next_z = NIL;
114	
115	            if num_merges <= 1 {
116	                return list;
117	            }
118	
119	            in_size *= 2;
